cat > $D/CalculateLoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static LoyaltyDiscountQuote Quote(int subtotal, LoyaltyTier tier, string? code = null) =>
        new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotal, tier, code));

    private static void AssertQuote(LoyaltyDiscountQuote quote, int discount, int total)
    {
        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 500, 9500)]
    [InlineData(LoyaltyTier.Silver, 1000, 9000)]
    [InlineData(LoyaltyTier.Gold, 1500, 8500)]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(10000, tier), discount, total);

    // The loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2000, 18000)]
    [InlineData(30000, LoyaltyTier.Silver, 2000, 28000)]
    [InlineData(12000, LoyaltyTier.Gold, 1800, 10200)]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier), discount, total);

    // No loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData(2999, 0, 2999)]
    [InlineData(3000, 450, 2550)]
    public void S3_NoLoyaltyDiscountUnderThirtyEuros(int subtotal, int discount, int total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Gold), discount, total);

    // The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1500, 8500)]
    [InlineData(2000, LoyaltyTier.Bronze, 500, 1500)]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    // The cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2500, 17500)]
    [InlineData(30000, LoyaltyTier.Silver, 2500, 27500)]
    public void S5_CapAppliesToLoyaltyDiscountOnlyNeverToWelcome5(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    // Promo codes ignore case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        Assert.Equal(1500, Quote(10000, LoyaltyTier.Silver, code).DiscountCents);

    // The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1900, 8100)]
    [InlineData(30000, LoyaltyTier.Bronze, 3000, 27000)]
    [InlineData(2000, LoyaltyTier.Gold, 200, 1800)]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMostFifteenEuros(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier, "SUMMER10"), discount, total);

    // An unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote(Quote(10000, LoyaltyTier.Silver, "SPRING"), 1000, 9000);

    // Platinum members receive a 20 % loyalty discount
    [Theory]
    [InlineData(10000, 2000, 8000)]
    [InlineData(5000, 1000, 4000)]
    [InlineData(20000, 2000, 18000)]
    public void S9_PlatinumMembersReceiveTwentyPercentLoyaltyDiscount(int subtotal, int discount, int total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Platinum), discount, total);

    // The discount never exceeds the subtotal
    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_DiscountNeverExceedsTheSubtotal(int subtotal, LoyaltyTier tier, int discount) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, 0);
}
E
cat > $D/CalculateShippingFeeAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class CalculateShippingFeeAcceptanceTests
{
    private static int Fee(int payable, LoyaltyTier tier, bool express = false) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payable, tier, express));

    // Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData(4999, LoyaltyTier.Bronze, 490)]
    [InlineData(5000, LoyaltyTier.Bronze, 0)]
    [InlineData(4999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(int total, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, Fee(total, tier));

    // Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(0, Fee(1000, tier));

    // Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData(10000, LoyaltyTier.Bronze, 990)]
    [InlineData(1000, LoyaltyTier.Gold, 990)]
    [InlineData(1000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNinetyNineHundredthsFreeForPlatinumOnly(int total, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, Fee(total, tier, express: true));
}
E
cat > $D/QuoteCheckoutAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class QuoteCheckoutAcceptanceTests
{
    // The checkout quote adds shipping to the payable total
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, "WELCOME5", false, 8500, 0, 8500)]
    [InlineData(5000, LoyaltyTier.Bronze, null, false, 4750, 490, 5240)]
    [InlineData(20000, LoyaltyTier.Platinum, "SUMMER10", true, 16500, 0, 16500)]
    [InlineData(2000, LoyaltyTier.Gold, null, true, 2000, 990, 2990)]
    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
        int subtotal, LoyaltyTier tier, string? code, bool express, int payable, int fee, int total)
    {
        var quote = new QuoteCheckout().Handle(new QuoteCheckoutQuery(subtotal, tier, code, express));

        Assert.Equal(payable, quote.PayableCents);
        Assert.Equal(fee, quote.ShippingCents);
        Assert.Equal(total, quote.TotalCents);
    }
}
